def qr_dialog():
    return '''<dialog id="accountQr" class="connection-dialog" aria-labelledby="qrDialogTitle"><header class="connection-header"><div class="connection-heading"><small>ДОСТУП К КЛИЕНТУ</small><h2 id="qrDialogTitle">Подключение</h2></div><button type="button" class="connection-close" data-close-dialog aria-label="Закрыть QR">×</button></header><div class="connection-body"><section class="connection-info"><div class="connection-person"><span id="qrInitial" class="client-initial" aria-hidden="true"></span><div><h3 id="qrClientName"></h3><p id="qrKind" class="connection-kind"></p></div></div><div id="qrProtocol" class="connection-protocol"></div><div class="connection-meta"><span><small>Сервер</small><b id="qrHost"></b></span><span id="qrPortRow" hidden><small>Порт</small><b id="qrPort"></b></span></div></section><div class="qr-visual"><div class="qr-canvas" aria-busy="true"><img id="accountQrImage" alt="QR подключения" hidden><p id="qrImageStatus" role="status">Создаём QR…</p></div><button type="button" id="qrRetry" class="qr-retry quiet" hidden>Повторить загрузку</button><p class="qr-caption"><span id="qrStepOne"></span><br><span id="qrStepTwo"></span></p></div></div><footer class="connection-footer"><button type="button" class="primary" id="qrCopy">'''+icon('copy')+'''<span>Скопировать ссылку</span></button><p id="qrCopyStatus" class="connection-status" role="status"></p><details id="qrLinkDetails" class="connection-link"><summary>Показать ссылку вручную</summary><input id="qrLink" readonly aria-label="Ссылка подключения" spellcheck="false"></details><p class="connection-privacy">QR и ссылка открывают доступ к подключению.<br>Храните их как пароль.</p></footer></dialog>'''+QR_JS


QR_JS='''<script>
(()=>{const dialog=document.getElementById('accountQr'),image=document.getElementById('accountQrImage'),status=document.getElementById('qrImageStatus'),retry=document.getElementById('qrRetry'),canvas=dialog.querySelector('.qr-canvas'),copy=document.getElementById('qrCopy'),copyStatus=document.getElementById('qrCopyStatus'),link=document.getElementById('qrLink');let controller=null,objectUrl='',serial=0,endpoint='';
function clearImage(){image.hidden=true;image.removeAttribute('src');if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=''}}
async function loadQr(){const generation=++serial;if(controller)controller.abort();controller=new AbortController();clearImage();canvas.classList.remove('has-error');status.hidden=false;status.textContent='Создаём QR…';canvas.setAttribute('aria-busy','true');retry.hidden=true;try{const r=await fetch(endpoint,{signal:controller.signal,cache:'no-store'});if(r.redirected)throw new Error('Сессия завершена. Войдите в панель заново.');if(!r.ok||!r.headers.get('content-type')?.startsWith('image/png'))throw new Error('Не удалось создать QR. Обновите список и попробуйте ещё раз.');const blob=await r.blob();if(generation!==serial)return;objectUrl=URL.createObjectURL(blob);image.src=objectUrl;await image.decode();if(generation!==serial)return;image.hidden=false;status.hidden=true}catch(e){if(generation!==serial||e.name==='AbortError')return;clearImage();canvas.classList.add('has-error');status.textContent=e instanceof TypeError?'Нет связи с сервером. Проверьте соединение.':e.message||'Не удалось загрузить QR.';retry.hidden=false}finally{if(generation===serial)canvas.setAttribute('aria-busy','false')}}
const wide=matchMedia('(min-width:1440px)');let opener=null;
function selectedRow(q){document.querySelectorAll('[data-client]').forEach(row=>{const chosen=row===q?.closest('[data-client]');row.classList.toggle('qr-selected',chosen);const b=row.querySelector('[data-qr]');if(b)b.setAttribute('aria-expanded',String(chosen))})}
function openQr(q){let info;try{info=JSON.parse(q.dataset.qrInfo)}catch(e){return}opener=q;endpoint=q.dataset.qr;document.getElementById('qrClientName').textContent=info.name;document.getElementById('qrInitial').textContent=Array.from(info.name.trim())[0]?.toLocaleUpperCase('ru')||'•';document.getElementById('qrKind').textContent=info.kind==='subscription'?'Ссылка подписки':'Отдельное подключение';const protocols=document.getElementById('qrProtocol');protocols.replaceChildren();info.protocols.split(' · ').forEach(p=>{const badge=document.createElement('span');badge.className='pill';badge.textContent=p;protocols.appendChild(badge)});document.getElementById('qrHost').textContent=info.host;document.getElementById('qrPortRow').hidden=info.port===null;document.getElementById('qrPort').textContent=info.port??'';document.getElementById('qrStepOne').textContent=info.web?'Сканируйте камерой другого устройства.':'Отсканируйте в совместимом приложении';document.getElementById('qrStepTwo').textContent=info.web?'Откройте ссылку в Telegram.':'или скопируйте ссылку.';link.value=info.link;copyStatus.textContent='';copy.disabled=false;document.getElementById('qrLinkDetails').open=false;selectedRow(q);const dock=wide.matches&&!q.closest('dialog')&&!document.querySelector('dialog:modal');if(dialog.open&&dialog.classList.contains('docked')!==dock){dialog.close();return}dialog.classList.toggle('docked',dock);if(!dialog.open){if(dock)dialog.show();else dialog.showModal()}loadQr()}
document.addEventListener('click',e=>{const q=e.target.closest('[data-qr]');if(q)openQr(q)});
// Switching layout closes the private card instead of leaving a modal trapped off-screen.
wide.addEventListener('change',()=>{if(dialog.open)dialog.close()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog.open&&dialog.classList.contains('docked')&&!document.querySelector('dialog:modal')){e.preventDefault();dialog.close()}});
document.addEventListener('wpp-filtered',()=>{if(dialog.open&&opener?.closest('[data-client]')?.hidden)dialog.close()});
document.querySelectorAll('[data-open-client],#newAccount').forEach(b=>b.addEventListener('click',()=>{if(dialog.open)dialog.close()}));
retry.addEventListener('click',loadQr);copy.addEventListener('click',async()=>{const generation=serial;copy.disabled=true;try{await wppCopy(link.value,dialog);if(generation===serial)copyStatus.textContent='Ссылка скопирована — можно вставлять в приложение.'}catch(e){if(generation===serial){document.getElementById('qrLinkDetails').open=true;link.focus();link.select();copyStatus.textContent='Не удалось скопировать автоматически. Скопируйте выделенную ссылку.'}}finally{if(generation===serial)copy.disabled=false}});
dialog.addEventListener('close',()=>{++serial;if(controller)controller.abort();clearImage();canvas.classList.remove('has-error');link.value='';endpoint='';copyStatus.textContent='';selectedRow(null);dialog.classList.remove('docked');if(opener?.isConnected&&!opener.closest('[hidden]')&&!document.querySelector('dialog:modal'))opener.focus({preventScroll:true})});
})();
</script>'''

